var q = [tree.root]
var found := []
while not q.is_empty():
	var c = q.pop_front()
	if (c is Label or c is RichTextLabel) and c.is_visible_in_tree():
		var t := str(c.get_parsed_text()) if c is RichTextLabel else str(c.text)
		if t.contains("Sv:4+") or t.contains("Sv 4+"):
			found.append(t)
	for ch in c.get_children():
		q.append(ch)
print("[wp-o5] Sv labels: ", found)
return found.size() > 0

